from typing import List, Dict, Any
from leann.api import PassageManager, LeannSearcher
from pathlib import Path
import json
from collections import Counter, defaultdict


def _load_meta(index_path: str) -> Dict[str, Any]:
    """Load the LEANN meta.json for a given index_path.

    Raises FileNotFoundError if the metadata file does not exist.
    """
    # Normalize to absolute path the same way LeannSearcher does
    path = Path(index_path)
    if not path.is_absolute():
        path = path.resolve()

    meta_path = path.parent / f"{path.name}.meta.json"
    if not meta_path.exists():
        # Match the spirit of LeannSearcher but without extra ANSI text
        raise FileNotFoundError(f"Leann metadata file not found at {meta_path}")

    with open(meta_path, encoding="utf-8") as f:
        meta = json.load(f)
    return meta


def _iter_passages(meta: Dict[str, Any], meta_path_str: str):
    """Yield each passage record dict from all passage_sources.

    This reuses PassageManager's path resolution and offset map loading
    to ensure compatibility with LEANN's index layout.
    """
    passage_manager = PassageManager(
        meta.get("passage_sources", []), metadata_file_path=meta_path_str
    )

    # The PassageManager internally stores:
    #   self.offset_maps: {passage_file: {id: offset}}
    #   self.passage_files: {passage_file: passage_file}
    #
    # We want to iterate deterministically over all passages. For each shard
    # (passage_file), we walk the offset_map and read the line at the given
    # offset. This avoids having to know the raw .jsonl paths ourselves.
    for passage_file, offset_map in passage_manager.offset_maps.items():
        # Open once per shard for efficiency
        with open(passage_file, encoding="utf-8") as f:
            for passage_id, offset in offset_map.items():
                f.seek(offset)
                line = f.readline()
                if not line:
                    continue
                try:
                    record = json.loads(line)
                except json.JSONDecodeError:
                    continue
                yield record


def get_index_statistics(index_path: str) -> Dict[str, Any]:
    """Get comprehensive statistics about a LEANN index.

Args:
    index_path: Path to the LEANN index file

Returns:
    Dictionary containing:
    {
        "total_passages": total number of passages,
        "metadata_fields": list of unique metadata field names,
        "field_value_counts": dictionary of field value counts
    }

Raises:
    FileNotFoundError: If index metadata file is not found"""
    # Load metadata (raises FileNotFoundError if not present)
    meta = _load_meta(index_path)
    # Construct the meta path string in the same way as LeannSearcher
    path = Path(index_path)
    if not path.is_absolute():
        path = path.resolve()
    meta_path_str = str(path.parent / f"{path.name}.meta.json")

    total_passages = 0
    metadata_fields = set()
    field_value_counts: Dict[str, Counter] = defaultdict(Counter)

    for record in _iter_passages(meta, meta_path_str):
        total_passages += 1
        metadata = record.get("metadata", {}) or {}
        if not isinstance(metadata, dict):
            continue

        for field, value in metadata.items():
            metadata_fields.add(field)
            # Convert unhashable values (e.g., lists/dicts) to JSON strings
            try:
                field_value_counts[field][value] += 1
            except TypeError:
                field_value_counts[field][json.dumps(value, sort_keys=True)] += 1

    # Convert Counters to plain dicts for JSON-serializable output
    field_value_counts_serializable: Dict[str, Dict[Any, int]] = {
        field: dict(counter) for field, counter in field_value_counts.items()
    }

    return {
        "total_passages": total_passages,
        "metadata_fields": sorted(metadata_fields),
        "field_value_counts": field_value_counts_serializable,
    }


def analyze_index_coverage(index_path: str, required_fields: List[str]) -> Dict[str, Any]:
    """Analyze how well an index covers required metadata fields.

Args:
    index_path: Path to the LEANN index file
    required_fields: List of metadata field names that should be present

Returns:
    Dictionary containing:
    {
        "coverage_percentage": percentage of passages that have all required fields,
        "field_coverage": dictionary mapping field name to coverage percentage,
        "missing_fields": list of required fields not found in any passage
    }

Raises:
    FileNotFoundError: If index metadata file is not found"""
    # Load metadata (raises FileNotFoundError if not present)
    meta = _load_meta(index_path)
    path = Path(index_path)
    if not path.is_absolute():
        path = path.resolve()
    meta_path_str = str(path.parent / f"{path.name}.meta.json")

    total_passages = 0
    per_field_has_count: Dict[str, int] = {field: 0 for field in required_fields}
    all_fields_present_count = 0

    for record in _iter_passages(meta, meta_path_str):
        total_passages += 1
        metadata = record.get("metadata", {}) or {}
        if not isinstance(metadata, dict):
            metadata = {}

        # Track which required fields this passage has
        has_all = True
        for field in required_fields:
            if field in metadata:
                per_field_has_count[field] += 1
            else:
                has_all = False
        if has_all and required_fields:
            all_fields_present_count += 1

    # Avoid division by zero
    if total_passages == 0:
        coverage_percentage = 0.0
        field_coverage = {field: 0.0 for field in required_fields}
        missing_fields = list(required_fields)
    else:
        coverage_percentage = (all_fields_present_count / total_passages) * 100.0
        field_coverage = {
            field: (per_field_has_count[field] / total_passages) * 100.0
            for field in required_fields
        }
        # A field is "missing" if it never appears in any passage
        missing_fields = [field for field in required_fields if per_field_has_count[field] == 0]

    return {
        "coverage_percentage": coverage_percentage,
        "field_coverage": field_coverage,
        "missing_fields": missing_fields,
    }

